function reservedMaterialQuantity(code,warehouse){return state.productionJobs.filter(job=>job.status==='RELEASED').flatMap(job=>job.materials||[]).filter(material=>material.sku===code&&material.warehouse===warehouse).reduce((sum,material)=>sum+(+material.required||0),0)}
function compute(){
  const remaining=new Map(),details=[],summaries=[];
  const openOrders=state.orders.filter(o=>!['PLANNED','RELEASED','IN_PRODUCTION','AWAITING_FQC','QUALITY_HOLD','COMPLETED'].includes(o.productionStatus));
  for(const o of sortOrdersForAllocation(openOrders)){let ok=0,missing=0,incomplete=0,defined=0,first='';const lines=state.boms[o.productCode]||[];
    for(const l of lines){if(!l.sku)continue;defined++;const qty=Number(l.qty),waste=Math.max(0,Number(l.wastePercent)||0),factor=Number.isFinite(qty)?qty*(1+waste/100):0,need=Number(o.qty||0)*factor,warehouse=l.warehouse||sku(l.sku)?.warehouse||'WH-RM',key=`${l.sku}|${warehouse}`;if(!remaining.has(key))remaining.set(key,Math.max(0,(+state.stock[l.sku]?.[warehouse]||0)-reservedMaterialQuantity(l.sku,warehouse)));const available=remaining.get(key);let status='SUFFICIENT',shortage=0;
      if(!Number.isFinite(qty)||qty<=0){status='ENTER FACTOR';incomplete++;first||=l.sku}
      else if(available<need){status='SHORTAGE';shortage=need-available;missing++;first||=l.sku;remaining.set(key,0)}
      else{ok++;remaining.set(key,available-need)}
      details.push({orderNo:o.orderNo,productCode:o.productCode,productName:product(o.productCode)?.name||'',orderQty:+o.qty||0,priority:o.priority||'NORMAL',needDate:o.due||'',orderDate:o.date||'',sku:l.sku,name:sku(l.sku)?.name||l.name,warehouse,factor,need,available,shortage,status});
    }
    const result=!o.productCode?'EMPTY':incomplete?'INCOMPLETE BOM':missing?'NOT PRODUCIBLE':'PRODUCIBLE';summaries.push({order:o,defined,ok,missing,incomplete,first,result});
  }return {details,summaries};
}
