  $('#plannedSupplyOrderTable').onchange=e=>{if(!e.target.dataset.plannedField)return;const row=e.target.closest('tr[data-planned-order]');try{const quantity=row.querySelector('[data-planned-field="quantity"]').value,releaseDate=row.querySelector('[data-planned-field="releaseDate"]').value,needDate=row.querySelector('[data-planned-field="needDate"]').value,order=updatePlannedSupply(state,row.dataset.plannedOrder,{quantity:parseLocalizedNumber(quantity),releaseDate,needDate,user:planner});dirty('MRP_PLANNED_ORDER_UPDATED','PLANNED_ORDER',order.plannedOrderNo);renderAdvancedPlanning()}catch(error){toast(error.message);renderAdvancedPlanning()}};
