  const exceptions=plannedSupplyExceptions(state,{asOf:plan.asOf,horizonDays:plan.horizonDays});$('#mrpExceptionKpis').innerHTML=[['Action required',exceptions.actionRequired],['Review',exceptions.review],['Aligned',exceptions.aligned]].map(([label,value])=>`<div class="kpi">${label}<b>${value}</b></div>`).join('');$('#mrpExceptionTable').innerHTML='<thead><tr><th>Planned order</th><th>SKU</th><th>Current</th><th>Suggested</th><th>Current release</th><th>Suggested release</th><th>Message</th><th>Status</th><th></th></tr></thead><tbody>'+((exceptions.rows.map(item=>`<tr data-exception-order="${esc(item.plannedOrderId)}"><td><b>${esc(item.plannedOrderNo)}</b><br><small>${esc(item.sourceOrderNo)}</small></td><td>${esc(item.sku)}</td><td>${n(item.currentQuantity,4)}</td><td>${n(item.suggestedQuantity,4)}</td><td>${esc(item.currentReleaseDate||'—')}</td><td>${esc(item.suggestedReleaseDate||'—')}</td><td>${item.actions.map(chip).join(' ')}</td><td>${chip(item.severity)}</td><td><button data-apply-mrp-exception class="gate-action" ${item.status==='FIRM'&&item.suggestedQuantity>0&&item.actions[0]!=='ALIGNED'?'':'disabled'}>Replan</button></td></tr>`).join(''))||'<tr><td colspan="9">No open planned supply orders.</td></tr>')+'</tbody>';$('#mrpExceptionTable').onclick=e=>{const button=e.target.closest('[data-apply-mrp-exception]');if(!button)return;const exception=exceptions.rows.find(item=>item.plannedOrderId===button.closest('tr').dataset.exceptionOrder);try{const order=updatePlannedSupply(state,exception.plannedOrderId,{quantity:exception.suggestedQuantity,releaseDate:exception.suggestedReleaseDate,needDate:exception.suggestedNeedDate,user:planner});dirty('MRP_EXCEPTION_APPLIED','PLANNED_ORDER',order.plannedOrderNo,exception.actions.join(', '));renderAdvancedPlanning();toast(`${order.plannedOrderNo} replanned from current supply and demand.`)}catch(error){toast(error.message)}};
