const REPORT_LABELS={area:'Area',metric:'Metric',value:'Value',status:'Status',date:'Date & Time',warehouse:'Warehouse',sku:'SKU',description:'Description',unit:'Unit',quantity:'Quantity',unitCost:'Unit Cost',state:'Warehouse State',direction:'Direction',type:'Type',reference:'Reference',batch:'Batch',user:'User',device:'Device',workOrder:'Work Order',order:'Order',product:'Product',planned:'Planned',completed:'Completed',scrap:'Scrap',yield:'Yield %',plannedHours:'Planned h',actualHours:'Actual h',inspection:'Inspection',ncr:'NCR',disposition:'Disposition',released:'Released',notes:'Notes',po:'PO',pr:'PR',supplier:'Supplier',unitPrice:'Unit Price',total:'Total',due:'Due Date',grn:'GRN',invoice:'Invoice',customer:'Customer',payment:'Payment',shipment:'Shipment',shippingStatus:'Shipping Status',destination:'Destination',qc:'QC',manager:'Manager',action:'Action',entity:'Entity',role:'Role',workspace:'Workspace',details:'Details',engine:'Engine',statement:'Statement',line:'Line item',amount:'Amount',standard:'Standard',severity:'Severity',code:'Control',message:'Message'};
