function pageRows(key,rows){const pages=Math.max(1,Math.ceil(rows.length/LIST_PAGE_SIZE));listPages[key]=Math.min(listPages[key],pages-1);const start=listPages[key]*LIST_PAGE_SIZE;return rows.slice(start,start+LIST_PAGE_SIZE)}
