function renderProducts(){const q=$('#productSearch').value.toLowerCase(),allRows=state.products.map((x,i)=>({x,i})).filter(o=>(o.x.code+' '+o.x.name).toLowerCase().includes(q)),rows=pageRows('products',allRows);$('#productTable').innerHTML=`<thead><tr><th>${tx('Product Code','Ürün Kodu')}</th><th>${tx('Description','Açıklama')}</th><th>${tx('Unit','Birim')}</th><th>Planned Lead (h)</th><th>${tx('Notes','Notlar')}</th><th></th></tr></thead><tbody>`+rows.map(o=>`<tr data-index="${o.i}"><td>${input(o.x.code,'code')}</td><td>${input(o.x.name,'name')}</td><td>${optionSelect(o.x.unit,'unit',UNITS)}</td><td>${input(o.x.productionLeadTimeHours||8,'productionLeadTimeHours','number','min="0.1" step="0.1"')}</td><td>${input(o.x.notes,'notes')}</td><td><button data-delete class="delete">${tx('Delete','Sil')}</button></td></tr>`).join('')+'</tbody>';renderListPager('product','products',allRows.length,renderProducts);bindTable($('#productTable'),state.products,()=>{renderProducts();refreshLists();renderBom()})}
function renderSkus(){const q=$('#skuSearch').value.toLowerCase(),allRows=state.skus.map((x,i)=>({x,i})).filter(o=>(o.x.code+' '+o.x.name+' '+(o.x.barcode||'')).toLowerCase().includes(q)),rows=pageRows('skus',allRows);$('#skuTable').innerHTML=`<thead><tr><th>SKU</th><th>GTIN / Barcode</th><th>${tx('Description','Açıklama')}</th><th>${tx('Type','Tür')}</th><th>${tx('Unit','Birim')}</th><th>${tx('Cost','Maliyet')}</th><th>${tx('Main Warehouse','Ana Depo')}</th><th>Min</th><th>Max</th><th></th></tr></thead><tbody>`+rows.map(o=>`<tr data-index="${o.i}"><td>${input(o.x.code,'code')}</td><td>${input(o.x.barcode||'','barcode')}</td><td>${input(o.x.name,'name')}</td><td>${optionSelect(o.x.type,'type',ITEM_TYPES)}</td><td>${optionSelect(o.x.unit,'unit',UNITS)}</td><td>${input(o.x.cost,'cost','number','step="0.0001"')}</td><td>${warehouseSelect(o.x.warehouse,'warehouse')}</td><td>${input(o.x.min,'min','number')}</td><td>${input(o.x.max,'max','number')}</td><td><button data-delete class="delete">${tx('Delete','Sil')}</button></td></tr>`).join('')+'</tbody>';renderListPager('sku','skus',allRows.length,renderSkus);bindTable($('#skuTable'),state.skus,()=>{renderSkus();refreshLists();renderBom();updateReceiptDescription()})}
