function labelData(){const job=selectedDocumentJob()||{},code=job.productCode||state.products[0]?.code,profile=code?ensureBomProfile(state,code):{version:'',model:'',design:'',packageType:''},output=sku(job.outputSku);return{productName:job.productName||product(job.productCode)?.name||'',sku:job.outputSku||'',barcode:output?.barcode||job.outputSku||'',batchNo:job.batchNo||'',bomVersion:job.bomVersion||profile.version,model:job.model||profile.model,design:job.design||profile.design,packageType:job.packageType||profile.packageType,manufactureDate:$('#labelMfg').value,expiryDate:$('#labelExpiry').value,qty:$('#labelQty').value||job.completedQty||job.plannedQty||'',unit:product(job.productCode)?.unit||'ADET',warning:$('#labelWarning').value,image:labelImageData}}
function labelSettings(){return{width:$('#labelWidth').value,height:$('#labelHeight').value,orientation:$('#labelOrientation').value,margin:$('#labelMargin').value,labelsPerPage:$('#labelsPerPage').value,gap:$('#labelGap').value,barcodeStandard:state.settings.barcodeStandard||'EAN_13'}}
