function renderLabelPreview(){if(!$('#labelPreview'))return;const data=labelData(),settings=labelSettings(),landscape=settings.orientation==='landscape',width=Math.max(1,Number(landscape?settings.height:settings.width)||100),height=Math.max(1,Number(landscape?settings.width:settings.height)||150),ratio=Math.min(4,Math.max(.25,width/height));$('#labelPreview').innerHTML=`<div class="preview-sheet" style="--label-ratio:${ratio}"><h3>${esc(data.productName||'Product')}</h3><b>${esc(data.sku)}</b><div class="preview-meta"><span>Model: ${esc(data.model||'—')}</span><span>Design: ${esc(data.design||'—')}</span><span>Package: ${esc(data.packageType||'—')}</span><span>Batch: ${esc(data.batchNo||'—')}</span><span>BOM: ${esc(data.bomVersion||'—')}</span><span>Qty: ${esc(data.qty||'—')} ${esc(data.unit||'')}</span><span>Barcode: ${esc((state.settings.barcodeStandard||'EAN_13').replace('_','-'))}</span></div>${labelBarcodeMarkup(data)}</div>`}
function loadLabelImage(){const file=$('#labelImage').files?.[0];if(!file){labelImageData='';return renderLabelPreview()}const reader=new FileReader();reader.onload=()=>{const image=new Image();image.onload=()=>{const scale=Math.min(1,600/Math.max(image.width,image.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(image.width*scale));canvas.height=Math.max(1,Math.round(image.height*scale));canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);labelImageData=canvas.toDataURL('image/jpeg',.75);renderLabelPreview()};image.src=String(reader.result)};reader.readAsDataURL(file)}
