function printCartonLabel(){const job=selectedDocumentJob();if(!job)return;try{const data=labelData(),settings=labelSettings();normalizeRetailBarcode(data.barcode||data.sku,settings.barcodeStandard);openPrintDocument(cartonLabelHtml(data,settings));appendAudit(state,{...operationMeta(),action:'CARTON_LABEL_PRINTED',entity:'LABEL',reference:job.batchNo,details:`${$('#labelWidth').value}×${$('#labelHeight').value} mm · ${settings.barcodeStandard.replace('_','-')}`});dirty(null)}catch(e){toast(`${e.message} Enter a valid GTIN in Items & SKU.`)}}
function findScannedJob(value){const term=String(value||'').trim().toLowerCase();return state.productionJobs.find(job=>job.workOrderNo.toLowerCase()===term||job.batchNo.toLowerCase()===term||job.outputSku.toLowerCase()===term||String(sku(job.outputSku)?.barcode||'').toLowerCase()===term)}
async function startCameraScan(){if(!('BarcodeDetector'in window)){toast('Camera barcode detection is not supported here; use a USB scanner or enter the code manually.');return}try{scannerStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment'}});const video=$('#scannerVideo');video.srcObject=scannerStream;video.hidden=false;await video.play();const detector=new BarcodeDetector({formats:['code_128','qr_code','ean_13','ean_8','upc_a']});const scan=async()=>{if(!scannerStream)return;const codes=await detector.detect(video).catch(()=>[]);if(codes[0]?.rawValue){$('#shopFloorScan').value=codes[0].rawValue;stopCamera();const job=findScannedJob(codes[0].rawValue);if(job){$('#documentJobSelect').value=job.id;renderDocuments()}return}requestAnimationFrame(scan)};scan()}catch(e){toast(`Camera unavailable: ${e.message}`)}}
function stopCamera(){scannerStream?.getTracks().forEach(track=>track.stop());scannerStream=null;$('#scannerVideo').hidden=true}
function receiveShopFloor(){const job=findScannedJob($('#shopFloorScan').value);if(!job){toast('Scanned work order or batch was not found.');return}try{const meta=operationMeta();completeProductionJob(state,job.id,{completedQty:parseLocalizedNumber($('#shopFloorGoodQty').value),scrapQty:parseLocalizedNumber($('#shopFloorScrapQty').value)||0,completedAt:meta.at,inspectionId:crypto.randomUUID?.()||job.id+'-fqc',inspectionNo:id('FQC',state.qualityInspections),meta});dirty(null);renderAll();toast('Shop Floor receipt recorded in Quarantine; FQC is required.')}catch(e){toast(e.message)}}
async function analyzeWaybill(){const file=$('#waybillImage').files?.[0];if(!file){toast('Choose a waybill image first.');return}if(!cloud?.request){toast('Cloud sign-in is required for image recognition.');return}$('#waybillStatus').textContent='Reading image…';try{const image=await fileAsDataUrl(file);const result=await cloud.request('/api/mrp/waybill/analyze',{method:'POST',body:JSON.stringify({image,fileName:file.name,mimeType:file.type})});state.currentWaybill={id:crypto.randomUUID?.()||String(Date.now()),fileName:file.name,documentNo:result.documentNo||'',supplier:result.supplier||'',rows:(result.rows||[]).map(row=>({...row,sku:row.sku||'',qty:Number(row.qty)||1})),analyzedAt:result.analyzedAt,model:result.model,approved:false};$('#waybillStatus').textContent=`${state.currentWaybill.rows.length} row(s) extracted. Review SKU and quantity before printing or posting.`;dirty('WAYBILL_ANALYZED','WAYBILL',result.documentNo||file.name,`${state.currentWaybill.rows.length} rows`);renderWaybillTable()}catch(e){$('#waybillStatus').textContent=e.message;toast(e.message)}}
function fileAsDataUrl(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result));reader.onerror=()=>reject(reader.error);reader.readAsDataURL(file)})}
function renderWaybillTable(){const rows=state.currentWaybill?.rows||[];$('#waybillTable').innerHTML='<thead><tr><th>#</th><th>Recognized description</th><th>Matched SKU</th><th>Qty</th><th>Unit</th><th>Batch</th><th>Expiry</th></tr></thead><tbody>'+((rows.map((row,i)=>`<tr data-waybill="${i}"><td>${i+1}</td><td>${input(row.description||'','description')}</td><td><input data-field="sku" list="skuOptions" value="${esc(row.sku||'')}"></td><td>${input(row.qty||1,'qty','number')}</td><td>${input(row.unit||'','unit')}</td><td>${input(row.batchNo||'','batchNo')}</td><td>${input(row.expiryDate||'','expiryDate','date')}</td></tr>`).join(''))||'<tr><td colspan="7">No waybill rows extracted.</td></tr>')+'</tbody>';$('#waybillTable').onchange=e=>{const row=e.target.closest('tr[data-waybill]'),field=e.target.dataset.field;if(!row||!field)return;state.currentWaybill.rows[+row.dataset.waybill][field]=field==='qty'?parseLocalizedNumber(e.target.value):e.target.value;dirty()}}
function printWaybillLabels(){const rows=state.currentWaybill?.rows||[];if(!rows.length){toast('No reviewed waybill rows.');return}if(rows.some(row=>!state.skus.some(item=>item.code===row.sku))){toast('Every row must be matched to a valid SKU.');return}try{const settings={width:100,height:100,labelsPerPage:1,barcodeStandard:state.settings.barcodeStandard},labels=rows.map(row=>{const item=sku(row.sku);normalizeRetailBarcode(item?.barcode||row.sku,settings.barcodeStandard);return cartonLabelHtml({productName:item?.name,sku:row.sku,barcode:item?.barcode||row.sku,batchNo:row.batchNo,expiryDate:row.expiryDate,qty:row.qty,unit:row.unit,warning:`Waybill ${state.currentWaybill.documentNo||state.currentWaybill.fileName}`},settings)}),bodies=labels.map(html=>new DOMParser().parseFromString(html,'text/html').body.innerHTML).join('');openPrintDocument(labels[0].replace(/<body>[\s\S]*<\/body>/,`<body>${bodies}</body>`));state.currentWaybill.approved=true;state.currentWaybill.approvedAt=new Date().toISOString();state.currentWaybill.approvedBy=operationMeta();state.waybillImports.unshift(state.currentWaybill);appendAudit(state,{...operationMeta(),action:'INCOMING_LABELS_PRINTED',entity:'WAYBILL',reference:state.currentWaybill.documentNo||state.currentWaybill.fileName,details:`${rows.length} ${settings.barcodeStandard.replace('_','-')} labels`});dirty(null)}catch(e){toast(`${e.message} Enter a valid GTIN for every SKU.`)}}
