  const suggestionRows=suggestions.length?suggestions.map((x,i)=>`<tr data-suggestion="${i}"><td>${esc(x.sku)}</td><td>${esc(x.name)}</td><td>${esc(x.warehouse)}</td><td>${n(x.shortage,4)}</td><td>${n(x.openPrQty,4)}</td><td>${n(x.suggestedQty,4)}</td><td>${esc(x.orders.join(', '))}</td><td>${esc(x.priority.replaceAll('_',' '))}</td><td><button class="gate-action" data-create-pr>Create PR</button></td></tr>`).join(''):'<tr><td colspan="9">No uncovered MRP shortages.</td></tr>';
