function poGate(po){if(po.status==='DRAFT')return{label:'Approve PO',disabled:false};if(po.status==='APPROVED')return{label:'Receive to QA',disabled:false};if(po.status==='QUARANTINE')return{label:'Await IQC',disabled:true};if(po.status==='ACCEPTED')return{label:'Check match',disabled:false};if(po.status==='MATCHED')return{label:'Matched',disabled:true};return{label:po.status?.replaceAll('_',' ')||'Unavailable',disabled:true}}
function advancePurchaseOrder(i){const po=state.purchaseOrders[i],supplier=state.suppliers.find(x=>x.code===po.supplierCode),pr=state.purchaseRequests.find(x=>x.prNo===po.prNo);if(po.status==='DRAFT'){if(!supplier?.approved){toast(tx('Blocked: supplier is not approved in ASL.','Engellendi: tedarikçi ASL listesinde onaylı değil.'));return}if(!pr||pr.status!=='APPROVED'||pr.budgetStatus!=='APPROVED'){toast(tx('Blocked: PR and budget must be approved.','Engellendi: PR ve bütçe onaylı olmalıdır.'));return}if(!sku(po.sku)||!(+po.qty>0)){toast(tx('Blocked: valid SKU and quantity required.','Engellendi: geçerli SKU ve miktar gerekli.'));return}po.status='APPROVED'}else if(po.status==='APPROVED'){po.grnNo||=id('GRN',state.receipts);const receiptId=crypto.randomUUID?.()||String(Date.now()),inspectionId=crypto.randomUUID?.()||receiptId+'-qc';queueReceiptForApproval(state,{id:receiptId,inspectionId,inspectionNo:id('IQC',state.qualityInspections),date:new Date().toISOString().slice(0,10),reference:po.grnNo,sku:po.sku,description:sku(po.sku)?.name||'',targetWarehouse:sku(po.sku)?.warehouse||'WH-RM',qty:+po.qty||0,supplier:po.supplierCode,notes:'PO '+po.poNo+' | IQC pending',transactionType:'PURCHASE_GRN_QUARANTINE',postedAt:new Date().toISOString()});const inspection=state.qualityInspections.find(x=>x.id===inspectionId);inspection.reference=po.poNo;po.received=true;po.status='QUARANTINE'}else if(po.status==='ACCEPTED'){try{completeThreeWayMatch(state,po)}catch(error){toast(tx(error.message,'Üçlü eşleştirme için kabul edilmiş QC, GRN ve tedarikçi faturası gerekir.'));return}}dirty();renderAll()}

function addInspection(){state.qualityInspections.unshift({id:crypto.randomUUID?.()||String(Date.now()),inspectionNo:id('QC',state.qualityInspections),type:'IQC',reference:'',sku:'',qty:0,result:'PENDING',date:new Date().toISOString().slice(0,10),ncrNo:'',disposition:'HOLD',released:false,notes:''});dirty();renderQuality()}
function renderQuality(){const pending=state.qualityInspections.filter(x=>x.result==='PENDING').length,rejected=state.qualityInspections.filter(x=>x.result==='REJECTED').length,ncr=state.qualityInspections.filter(x=>x.ncrNo).length,released=state.qualityInspections.filter(x=>x.stockReleased||(!x.receiptId&&x.released)).length;$('#qualityKpis').innerHTML=[[tx('Pending inspection','Bekleyen kontrol'),pending],[tx('Rejected','Reddedilen'),rejected],['NCR',ncr],[tx('Released stock','Serbest bırakılan'),released]].map(x=>`<div class="kpi">${x[0]}<b>${n(x[1],0)}</b></div>`).join('');$('#qualityTable').innerHTML='<thead><tr><th>Inspection</th><th>Stage</th><th>Reference</th><th>SKU</th><th>Qty</th><th>Date</th><th>Result</th><th>NCR</th><th>Disposition</th><th>Notes</th><th>Gate</th><th></th></tr></thead><tbody>'+state.qualityInspections.map((x,i)=>`<tr data-index="${i}"><td>${input(x.inspectionNo,'inspectionNo')}</td><td>${selectValues(x.type,'type',['IQC','IPQC','FQC','OQC'])}</td><td>${input(x.reference,'reference')}</td><td><input data-field="sku" list="skuOptions" value="${esc(x.sku)}"></td><td>${input(x.qty,'qty','number','min="0" step="any"')}</td><td>${input(x.date,'date','date')}</td><td>${selectValues(x.result,'result',['PENDING','ACCEPTED','CONDITIONAL','REJECTED'])}</td><td>${input(x.ncrNo,'ncrNo')}</td><td>${selectValues(x.disposition,'disposition',['HOLD','REWORK','RETURN_TO_SUPPLIER','SCRAP','USE_AS_IS'])}</td><td>${input(x.notes,'notes')}</td><td><button class="gate-action" data-qc-action ${x.released?'disabled':''}>${x.released?(x.receiptId&&x.result==='ACCEPTED'?'Await manager':'Decision applied'):'Apply decision'}</button></td><td><button data-delete class="delete">Delete</button></td></tr>`).join('')+'</tbody>';$('#qualityTable').onchange=e=>processEdit(e,state.qualityInspections,renderQuality);$('#qualityTable').onclick=e=>{const row=e.target.closest('tr[data-index]');if(!row)return;const i=+row.dataset.index;if(e.target.closest('[data-delete]')){state.qualityInspections.splice(i,1);dirty();renderQuality();return}if(e.target.closest('[data-qc-action]'))applyQualityDecision(i)}}
function applyQualityDecision(i){const q=state.qualityInspections[i];if(q.result==='PENDING'){toast(tx('Select a QC result first.','Önce QC sonucu seçin.'));return}if(q.productionJobId){try{const ncrNo=['CONDITIONAL','REJECTED'].includes(q.result)&&!q.ncrNo?id('NCR',state.qualityInspections.filter(x=>x.ncrNo)):q.ncrNo;applyProductionQualityDecision(state,q.id,{ncrNo,meta:operationMeta()});dirty(null);renderAll();toast(q.result==='ACCEPTED'?'FQC accepted; batch posted from Quarantine to Product warehouse.':'FQC hold applied; batch remains in Quarantine under NCR.');return}catch(e){toast(e.message);return}}if(q.receiptId){try{const ncrNo=['CONDITIONAL','REJECTED'].includes(q.result)&&!q.ncrNo?id('NCR',state.qualityInspections.filter(x=>x.ncrNo)):q.ncrNo;const receipt=applyReceiptQcDecision(state,q.id,ncrNo);const po=state.purchaseOrders.find(x=>x.poNo===q.reference);if(po&&receipt.status==='HOLD_NCR')po.status=q.result;dirty();renderAll();toast(receipt.status==='PENDING_MANAGER'?tx('QC accepted; manager approval is required before posting.','QC kabul etti; kayıt için yönetici onayı gerekli.'):tx('NCR created; stock remains in quarantine.','NCR oluşturuldu; stok karantinada kalır.'));return}catch(e){toast(e.message);return}}if(['CONDITIONAL','REJECTED'].includes(q.result)&&!q.ncrNo){q.ncrNo=id('NCR',state.qualityInspections.filter(x=>x.ncrNo));toast(tx('NCR created; stock remains in quarantine.','NCR oluşturuldu; stok karantinada kalır.'))}if(q.type==='IQC'&&q.result==='ACCEPTED'&&!q.released){const amount=Math.min(+q.qty||0,+state.stock[q.sku]?.['WH-QA']||0),dest=sku(q.sku)?.warehouse||'WH-RM';if(amount<=0){toast(tx('No matching quarantine stock.','Eşleşen karantina stoku yok.'));return}state.stock[q.sku]['WH-QA']-=amount;state.stock[q.sku][dest]=(+state.stock[q.sku][dest]||0)+amount;q.released=true;const po=state.purchaseOrders.find(x=>x.poNo===q.reference);if(po)po.status='ACCEPTED'}else if(q.type==='FQC'){const order=state.salesOrders.find(x=>x.orderNo===q.reference);if(order){order.qcStatus=q.result;order.status=order.reservedQty&&q.result==='ACCEPTED'&&(order.paymentStatus==='PAID'||order.creditApproved)?'READY_TO_SHIP':order.reservedQty?'RESERVED':'DRAFT'}q.released=true}else if(q.type==='OQC'){const shipment=state.shipments.find(x=>x.shipmentNo===q.reference);if(shipment)shipment.oqcStatus=q.result;q.released=true}else if(q.result!=='ACCEPTED')q.released=true;dirty();renderAll()}

function addSalesOrder(){state.salesOrders.unshift({id:crypto.randomUUID?.()||String(Date.now()),orderNo:id('SO',state.salesOrders),date:new Date().toISOString().slice(0,10),customer:'',sku:'',qty:0,unitPrice:0,dueDate:'',paymentStatus:'PENDING',creditApproved:false,qcStatus:'PENDING',status:'DRAFT',reservedQty:0,notes:''});dirty();renderSales()}
function renderSales(){const draft=state.salesOrders.filter(x=>x.status==='DRAFT').length,reserved=state.salesOrders.filter(x=>x.status==='RESERVED').length,blocked=state.salesOrders.filter(x=>x.status==='BLOCKED').length,ready=state.salesOrders.filter(x=>x.status==='READY_TO_SHIP').length;$('#salesKpis').innerHTML=[[tx('Draft orders','Taslak sipariş'),draft],[tx('Reserved','Rezerve'),reserved],[tx('Blocked','Engelli'),blocked],[tx('Ready to ship','Sevke hazır'),ready]].map(x=>`<div class="kpi">${x[0]}<b>${n(x[1],0)}</b></div>`).join('');$('#salesOrderTable').innerHTML='<thead><tr><th>Sales Order</th><th>Date</th><th>Customer</th><th>Finished SKU</th><th>Qty</th><th>Price</th><th>Due</th><th>Payment</th><th>Credit</th><th>FQC</th><th>Status</th><th>ATP Gate</th><th></th></tr></thead><tbody>'+state.salesOrders.map((x,i)=>`<tr data-index="${i}"><td>${input(x.orderNo,'orderNo')}</td><td>${input(x.date,'date','date')}</td><td>${input(x.customer,'customer')}</td><td><input data-field="sku" list="skuOptions" value="${esc(x.sku)}"></td><td>${input(x.qty,'qty','number','min="0" step="any"')}</td><td>${input(x.unitPrice,'unitPrice','number','min="0" step=".01"')}</td><td>${input(x.dueDate,'dueDate','date')}</td><td>${selectValues(x.paymentStatus,'paymentStatus',['PENDING','PARTIAL','PAID','CREDIT'])}</td><td><input data-field="creditApproved" type="checkbox" ${x.creditApproved?'checked':''}></td><td>${selectValues(x.qcStatus,'qcStatus',['PENDING','ACCEPTED','REJECTED'])}</td><td>${chip(x.status)}</td><td><button class="gate-action" data-sales-action ${x.status==='SHIPPED'?'disabled':''}>${x.status==='DRAFT'||x.status==='BLOCKED'?'Check & reserve':'Recheck gates'}</button></td><td><button data-delete class="delete">Delete</button></td></tr>`).join('')+'</tbody>';$('#salesOrderTable').onchange=e=>processEdit(e,state.salesOrders,renderSales);$('#salesOrderTable').onclick=e=>{const row=e.target.closest('tr[data-index]');if(!row)return;const i=+row.dataset.index;if(e.target.closest('[data-delete]')){releaseReservation(state.salesOrders[i]);state.salesOrders.splice(i,1);dirty();renderSales();return}if(e.target.closest('[data-sales-action]'))reserveSalesOrder(i)}}
function releaseReservation(o){if(!o?.reservedQty)return;state.stock[o.sku]??={};state.stock[o.sku].reserved=Math.max(0,(+state.stock[o.sku].reserved||0)-(+o.reservedQty||0));o.reservedQty=0}
function reserveSalesOrder(i){const o=state.salesOrders[i],available=+state.stock[o.sku]?.['WH-FG']||0,reserved=+state.stock[o.sku]?.reserved||0,own=+o.reservedQty||0,free=available-reserved+own;releaseReservation(o);if(!sku(o.sku)||!(+o.qty>0)||free<+o.qty){o.status='BLOCKED';toast(tx('Blocked: insufficient finished-goods stock.','Engellendi: mamul stok yetersiz.'));dirty();renderAll();return}state.stock[o.sku]??={};state.stock[o.sku].reserved=(+state.stock[o.sku].reserved||0)+(+o.qty||0);o.reservedQty=+o.qty||0;o.status=o.qcStatus==='ACCEPTED'&&(o.paymentStatus==='PAID'||o.creditApproved)?'READY_TO_SHIP':'RESERVED';dirty();renderAll()}

function addFinanceApproval(){state.financeApprovals.unshift({id:crypto.randomUUID?.()||String(Date.now()),approvalNo:id('FIN',state.financeApprovals),type:'SALES_RELEASE',reference:'',amount:0,documentMatch:false,qcApproved:false,creditApproved:false,status:'PENDING',notes:''});dirty();renderShipping()}
function addShipment(){state.shipments.unshift({id:crypto.randomUUID?.()||String(Date.now()),shipmentNo:id('SHP',state.shipments),orderNo:'',pickQty:0,packingList:'',invoiceNo:'',oqcStatus:'PENDING',shippingRelease:'BLOCKED',podNo:'',status:'DRAFT'});dirty();renderShipping()}
function renderShipping(){const financePending=state.financeApprovals.filter(x=>x.status==='PENDING').length,releaseBlocked=state.shipments.filter(x=>x.shippingRelease==='BLOCKED').length,ready=state.shipments.filter(x=>x.shippingRelease==='RELEASED'&&x.status!=='SHIPPED').length,shipped=state.shipments.filter(x=>x.status==='SHIPPED').length;$('#shippingKpis').innerHTML=[[tx('Finance pending','Finans bekliyor'),financePending],[tx('Release blocked','Çıkış engelli'),releaseBlocked],[tx('Ready','Hazır'),ready],[tx('Shipped','Sevk edildi'),shipped]].map(x=>`<div class="kpi">${x[0]}<b>${n(x[1],0)}</b></div>`).join('');$('#financeTable').innerHTML='<thead><tr><th>Approval</th><th>Type</th><th>Reference</th><th>Amount</th><th>Docs match</th><th>QC</th><th>Credit</th><th>Status</th><th>Gate</th><th></th></tr></thead><tbody>'+state.financeApprovals.map((x,i)=>`<tr data-index="${i}"><td>${input(x.approvalNo,'approvalNo')}</td><td>${selectValues(x.type,'type',['PURCHASE_PAYMENT','SALES_RELEASE'])}</td><td>${input(x.reference,'reference')}</td><td>${input(x.amount,'amount','number','min="0" step=".01"')}</td><td><input data-field="documentMatch" type="checkbox" ${x.documentMatch?'checked':''}></td><td><input data-field="qcApproved" type="checkbox" ${x.qcApproved?'checked':''}></td><td><input data-field="creditApproved" type="checkbox" ${x.creditApproved?'checked':''}></td><td>${chip(x.status)}</td><td><button class="gate-action" data-fin-action>Validate</button></td><td><button data-delete class="delete">Delete</button></td></tr>`).join('')+'</tbody>';$('#financeTable').onchange=e=>processEdit(e,state.financeApprovals,renderShipping);$('#financeTable').onclick=e=>{const row=e.target.closest('tr[data-index]');if(!row)return;const i=+row.dataset.index;if(e.target.closest('[data-delete]')){state.financeApprovals.splice(i,1);dirty();renderShipping();return}if(e.target.closest('[data-fin-action]'))validateFinance(i)};$('#shipmentTable').innerHTML='<thead><tr><th>Shipment</th><th>Sales Order</th><th>Pick Qty</th><th>Packing list</th><th>Invoice</th><th>OQC</th><th>Release</th><th>POD</th><th>Status</th><th>Gate</th><th></th></tr></thead><tbody>'+state.shipments.map((x,i)=>`<tr data-index="${i}"><td>${input(x.shipmentNo,'shipmentNo')}</td><td>${input(x.orderNo,'orderNo')}</td><td>${input(x.pickQty,'pickQty','number','min="0" step="any"')}</td><td>${input(x.packingList,'packingList')}</td><td>${input(x.invoiceNo,'invoiceNo')}</td><td>${selectValues(x.oqcStatus,'oqcStatus',['PENDING','ACCEPTED','REJECTED'])}</td><td>${chip(x.shippingRelease)}</td><td>${input(x.podNo,'podNo')}</td><td>${chip(x.status)}</td><td><button class="gate-action" data-ship-action ${x.status==='SHIPPED'?'disabled':''}>${x.shippingRelease==='RELEASED'?'Post shipment':'Check release'}</button></td><td><button data-delete class="delete">Delete</button></td></tr>`).join('')+'</tbody>';$('#shipmentTable').onchange=e=>processEdit(e,state.shipments,renderShipping);$('#shipmentTable').onclick=e=>{const row=e.target.closest('tr[data-index]');if(!row)return;const i=+row.dataset.index;if(e.target.closest('[data-delete]')){state.shipments.splice(i,1);dirty();renderShipping();return}if(e.target.closest('[data-ship-action]'))advanceShipment(i)}}
function validateFinance(i){const a=state.financeApprovals[i];a.status=a.documentMatch&&a.qcApproved&&(a.type==='PURCHASE_PAYMENT'||a.creditApproved)?'APPROVED':'BLOCKED';if(a.status==='BLOCKED')toast(tx('Blocked: document, QC and credit gates are incomplete.','Engellendi: belge, QC ve kredi kontrolleri eksik.'));dirty();renderAll()}
function advanceShipment(i){const s=state.shipments[i],o=state.salesOrders.find(x=>x.orderNo===s.orderNo),fin=state.financeApprovals.find(x=>x.type==='SALES_RELEASE'&&x.reference===s.orderNo&&x.status==='APPROVED');if(s.shippingRelease!=='RELEASED'){if(!o||o.status!=='READY_TO_SHIP'||!fin||s.oqcStatus!=='ACCEPTED'||!s.packingList||!s.invoiceNo||!(+s.pickQty>0)||+s.pickQty>+o.reservedQty){s.shippingRelease='BLOCKED';toast(tx('Blocked: reservation, finance, OQC, picking, packing list or invoice is incomplete.','Engellendi: rezervasyon, finans, OQC, toplama, paket listesi veya fatura eksik.'));dirty();renderShipping();return}s.shippingRelease='RELEASED';s.status='READY'}else{state.stock[o.sku]['WH-FG']=Math.max(0,(+state.stock[o.sku]['WH-FG']||0)-(+s.pickQty||0));state.stock[o.sku].reserved=Math.max(0,(+state.stock[o.sku].reserved||0)-(+s.pickQty||0));o.reservedQty=Math.max(0,(+o.reservedQty||0)-(+s.pickQty||0));s.status='SHIPPED';o.status=o.reservedQty?'PARTIALLY_SHIPPED':'SHIPPED'}dirty();renderAll()}

function processEdit(e,collection,rerender){const el=e.target.closest('[data-field]'),row=e.target.closest('tr[data-index]');if(!el||!row)return;const item=collection[+row.dataset.index];item[el.dataset.field]=el.type==='checkbox'?el.checked:el.dataset.number?parseLocalizedNumber(el.value):el.value;dirty();rerender()}
