function addExchangeListing(){state.exchangeListings.unshift({id:crypto.randomUUID?.()||String(Date.now()),sku:'',description:'',category:'',qty:0,unit:'ADET',askingPrice:0,location:'Istanbul',condition:'NEW',seller:state.company||'Hamvara',contact:'',status:'ACTIVE',createdAt:new Date().toISOString().slice(0,10)});dirty();renderExchange();renderDashboard()}
function suggestExcessListings(){let added=0;for(const x of state.skus){const excess=Math.max(0,totalStock(x.code)-(+x.max||0));if(excess<=0||state.exchangeListings.some(l=>l.sku===x.code&&['ACTIVE','NEGOTIATION'].includes(l.status)))continue;state.exchangeListings.unshift({id:crypto.randomUUID?.()||x.code+'-'+Date.now(),sku:x.code,description:x.name||'',category:x.type||'',qty:excess,unit:x.unit||'ADET',askingPrice:+x.cost||0,location:'Istanbul',condition:'NEW',seller:state.company||'Hamvara',contact:'',status:'ACTIVE',createdAt:new Date().toISOString().slice(0,10),source:'AUTO_EXCESS'});added++}if(added){dirty();renderExchange();renderDashboard()}toast(added?tx(added+' excess item(s) added as draft listings.',added+' fazla stok ilan olarak eklendi.'):tx('No new excess stock found.','Yeni fazla stok bulunamadı.'))}
function renderExchange(){const el=$('#exchangeTable');if(!el)return;const q=($('#exchangeSearch')?.value||'').toLowerCase(),rows=state.exchangeListings.map((x,i)=>({x,i})).filter(o=>(o.x.sku+' '+o.x.description+' '+o.x.location+' '+o.x.seller).toLowerCase().includes(q));const active=state.exchangeListings.filter(x=>x.status==='ACTIVE').length,neg=state.exchangeListings.filter(x=>x.status==='NEGOTIATION').length,sold=state.exchangeListings.filter(x=>x.status==='SOLD').length,value=state.exchangeListings.filter(x=>x.status==='ACTIVE').reduce((s,x)=>s+(+x.qty||0)*(+x.askingPrice||0),0);$('#exchangeKpis').innerHTML=[[tx('Active Listings','Aktif İlanlar'),active],[tx('In Negotiation','Görüşmede'),neg],[tx('Sold','Satıldı'),sold],[tx('Listed Value','İlan Değeri'),n(value)+' '+esc(state.settings.currency||'TRY')]].map(x=>`<div class="kpi">${x[0]}<b>${x[1]}</b></div>`).join('');el.innerHTML=`<thead><tr><th>SKU</th><th>${tx('Description','Açıklama')}</th><th>${tx('Quantity','Miktar')}</th><th>${tx('Unit','Birim')}</th><th>${tx('Unit Price','Birim Fiyat')}</th><th>${tx('Location','Konum')}</th><th>${tx('Condition','Durum')}</th><th>${tx('Seller','Satıcı')}</th><th>${tx('Contact','İletişim')}</th><th>${tx('Listing Status','İlan Durumu')}</th><th></th></tr></thead><tbody>`+rows.map(o=>`<tr data-index="${o.i}"><td><input data-exchange="sku" list="skuOptions" value="${esc(o.x.sku)}"></td><td>${input(o.x.description,'description')}</td><td>${input(o.x.qty,'qty','number','min="0" step="0.0001"')}</td><td>${optionSelect(o.x.unit,'unit',UNITS)}</td><td>${input(o.x.askingPrice,'askingPrice','number','min="0" step="0.01"')}</td><td>${input(o.x.location,'location')}</td><td><select data-exchange="condition">${['NEW','GOOD','INSPECT','EXPIRING'].map(v=>`<option value="${v}" ${o.x.condition===v?'selected':''}>${exchangeCondition(v)}</option>`).join('')}</select></td><td>${input(o.x.seller,'seller')}</td><td>${input(o.x.contact,'contact')}</td><td><select data-exchange="status">${['ACTIVE','NEGOTIATION','SOLD','ARCHIVED'].map(v=>`<option value="${v}" ${o.x.status===v?'selected':''}>${exchangeStatus(v)}</option>`).join('')}</select></td><td><button data-exchange-delete class="delete">${tx('Delete','Sil')}</button></td></tr>`).join('')+'</tbody>';el.onchange=e=>{const row=e.target.closest('tr[data-index]');if(!row)return;const item=state.exchangeListings[+row.dataset.index],field=e.target.dataset.exchange||e.target.dataset.field;if(!field)return;item[field]=e.target.dataset.number?parseLocalizedNumber(e.target.value):e.target.value;if(field==='sku'){const x=sku(item.sku);item.description=x?.name||item.description;item.unit=x?.unit||item.unit;item.category=x?.type||item.category;item.askingPrice=item.askingPrice||(+x?.cost||0)}dirty();renderExchange();renderDashboard()};el.onclick=e=>{if(!e.target.closest('[data-exchange-delete]'))return;state.exchangeListings.splice(+e.target.closest('tr').dataset.index,1);dirty();renderExchange();renderDashboard()}}

function renderImportContract(){const table=$('#importContractTable');if(!table)return;table.innerHTML='<thead><tr><th>Data type</th><th>Required fields</th><th>Optional fields</th><th>Duplicate key</th></tr></thead><tbody>'+Object.entries(IMPORT_SCHEMAS).map(([entity,schema])=>{const required=Object.entries(schema.fields).filter(([,field])=>field.required).map(([,field])=>field.label),optional=Object.entries(schema.fields).filter(([,field])=>!field.required).map(([,field])=>field.label);return `<tr><td>${esc(schema.label)}</td><td>${esc(required.join(', '))}</td><td>${esc(optional.join(', '))}</td><td>${esc(schema.key.map(key=>schema.fields[key]?.label||key).join(' + '))}</td></tr>`}).join('')+'</tbody>'}
function downloadUniversalContract(){const rows=Object.entries(IMPORT_SCHEMAS).flatMap(([,schema])=>Object.entries(schema.fields).map(([key,field])=>[schema.label,key,field.label,field.required?'YES':'NO',field.type,field.aliases.join(' | '),schema.key.includes(key)?'DUPLICATE KEY':'']));downloadWorkbook('Hamvara_Universal_Import_Contract.xlsx','Import Contract',['Data Type','Canonical Field','Standard Header','Required','Data Type','Accepted Header Examples','Rule'],rows);toast('Universal import contract downloaded.')}
async function analyzeUniversalFile(file){try{const source=await readTabularFile(file);if(!source.rows.length)throw Error('File has no data rows');universalSource={...source,fileName:file.name,entity:'',mapping:{}};prepareUniversalMapping()}catch(error){universalSource=null;$('#universalMappingPanel').hidden=true;$('#universalFileStatus').textContent='Import file error: '+error.message;toast('Import file error: '+error.message)}}
function prepareUniversalMapping(){const selected=$('#universalEntity').value,detection=detectImportEntity(universalSource.headers),entity=selected==='auto'?detection.entity:selected,mapping=suggestMapping(universalSource.headers,entity),schema=IMPORT_SCHEMAS[entity];universalSource.entity=entity;universalSource.mapping=mapping;if(selected==='auto')$('#universalEntity').value=entity;$('#universalFileStatus').textContent=`${universalSource.fileName} · ${universalSource.format} · ${universalSource.rows.length} row(s) · detected as ${schema.label}`;$('#universalMappingTable').innerHTML='<thead><tr><th>Hamvara field</th><th>Required</th><th>Source column</th><th>Accepted type</th></tr></thead><tbody>'+Object.entries(schema.fields).map(([key,field])=>`<tr><td>${esc(field.label)}</td><td>${field.required?'YES':'—'}</td><td><select data-map-field="${esc(key)}"><option value="">Ignore / not supplied</option>${universalSource.headers.map(header=>`<option value="${esc(header)}" ${mapping[key]===header?'selected':''}>${esc(header)}</option>`).join('')}</select></td><td>${esc(field.type)}</td></tr>`).join('')+'</tbody>';$('#universalMappingTable').onchange=e=>{const key=e.target.dataset.mapField;if(key)universalSource.mapping[key]=e.target.value};$('#universalMappingPanel').hidden=false}
function universalWarehouse(value){const supplied=String(value??'').trim();return supplied?(resolveOpeningWarehouse(state,supplied,'WH-RM')||null):''}
function validateUniversalImport(){
  if(!universalSource)return;
  const {entity,mapping}=universalSource,mapped=universalSource.rows.map((row,index)=>{
    const clean=canonicalizeRow(row,entity,mapping,{parseNumber:parseLocalizedNumber,parseDate:isoDate,parseWarehouse:universalWarehouse,parseUnit:resolveOpeningUnit}),errors=validateCanonicalRow(clean,entity),warnings=[];
    if(entity==='skus'&&!mapping.quantity)warnings.push('No quantity mapped; item will be imported without changing stock');
    if(entity==='skus'&&clean.barcode){try{clean.barcode=normalizeRetailBarcode(clean.barcode,state.settings.barcodeStandard).value}catch(error){errors.push(error.message)}}
    if(entity==='bom'){if(!product(clean.productCode))warnings.push('Product must exist before this BOM can be used');if(!sku(clean.component))warnings.push('Component SKU must exist before this BOM can be used')}
    if(['salesOrders','purchaseRequests','purchaseOrders','receipts','quality'].includes(entity)&&clean.sku&&!sku(clean.sku))warnings.push('Referenced SKU is not currently in Hamvara');
    if(['suppliers','purchaseRequests','purchaseOrders','quality','shipments'].includes(entity))warnings.push('Workflow approvals from external files are not trusted; the record enters Hamvara as pending/draft');
    return{row,index:index+2,status:errors.length?'BLOCKED':'READY',errors,warnings,clean,key:importKey(clean,entity)}
  }),analysis=analyzeCanonicalRows(mapped,entity);
  const seenKeys=new Set();
  for(const result of mapped){
    if(result.key&&seenKeys.has(result.key)){result.errors.push('Duplicate business key in file; merge or remove this row before posting');result.status='BLOCKED'}
    if(result.key)seenKeys.add(result.key)
  }
  importSession={type:'universal',entity,results:mapped,analysis,fileName:universalSource.fileName};importPage=0;renderImportReview()
}
function upsert(collection,item,keyFields){const existing=collection.find(row=>keyFields.every(key=>String(row[key]??'')===String(item[key]??'')));if(existing){const stableId=existing.id;Object.assign(existing,item);if(stableId)existing.id=stableId;return'updated'}collection.push(item);return'created'}
function normalizedStatus(value,fallback){return String(value||fallback).trim().toUpperCase().replace(/\s+/g,'_')}
function safeUniversalRecord(entity,clean){
  const record={...clean};
  if(entity==='suppliers')record.approved=false;
  if(entity==='purchaseRequests'){record.budgetStatus='PENDING';record.status='DRAFT'}
  if(entity==='purchaseOrders')record.status='DRAFT';
  if(entity==='quality')record.result='PENDING';
  if(entity==='shipments'){record.oqcStatus='PENDING';record.status='DRAFT'}
  return record
}
function postUniversalRecord(entity,c){const uid=()=>crypto.randomUUID?.()||String(Date.now()+Math.random());if(entity==='products')return upsert(state.products,{code:c.code,name:c.name,unit:c.unit||'ADET',productionLeadTimeHours:c.leadTimeHours||8,notes:c.notes||'',active:true},['code']);if(entity==='skus'){const item={code:c.code,name:c.name||c.code,type:c.type||'',category:c.category||'',unit:c.unit||'ADET',cost:c.cost??0,warehouse:c.warehouse||'WH-RM',supplier:c.supplier||'',leadTime:c.leadTime??0,min:c.min??0,max:c.max??0,active:true},result=upsert(state.skus,item,['code']);state.stock[c.code]??={};if(c.quantity!==null&&c.quantity!==undefined&&c.warehouse)state.stock[c.code][c.warehouse]=c.quantity;return result}if(entity==='customers'){state.customers??=[];return upsert(state.customers,{...c,active:true},['code'])}if(entity==='suppliers')return upsert(state.suppliers,{code:c.code,name:c.name,approved:!!c.approved,rating:c.rating??0,terms:c.terms||'',leadTime:c.leadTime??0},['code']);if(entity==='productionOrders')return upsert(state.orders,{id:uid(),orderNo:c.orderNo,date:c.date||new Date().toISOString().slice(0,10),customer:c.customer||'',productCode:c.productCode,qty:c.qty,due:c.due||'',priority:normalizedStatus(c.priority,'NORMAL'),notes:c.notes||''},['orderNo','productCode']);if(entity==='salesOrders')return upsert(state.salesOrders,{id:uid(),orderNo:c.orderNo,date:c.date||new Date().toISOString().slice(0,10),customer:c.customer,sku:c.sku,qty:c.qty,unitPrice:c.unitPrice??0,dueDate:c.dueDate||'',paymentStatus:normalizedStatus(c.paymentStatus,'PENDING'),creditApproved:!!c.creditApproved,qcStatus:'PENDING',status:'DRAFT',reservedQty:0,notes:c.notes||''},['orderNo','sku']);if(entity==='bom'){state.boms[c.productCode]??=[];const result=upsert(state.boms[c.productCode],{sku:c.component,name:sku(c.component)?.name||'',warehouse:c.warehouse,qty:c.qty,wastePercent:c.wastePercent??0},['sku','warehouse']);if(c.version){const profile=ensureBomProfile(state,c.productCode);profile.version=c.version;if(c.effectiveDate)profile.effectiveDate=c.effectiveDate}return result}if(entity==='purchaseRequests')return upsert(state.purchaseRequests,{id:uid(),prNo:c.prNo,date:c.date||new Date().toISOString().slice(0,10),requester:c.requester||'',sku:c.sku,qty:c.qty,needDate:c.needDate||'',priority:normalizedStatus(c.priority,'NORMAL'),budgetStatus:normalizedStatus(c.budgetStatus,'PENDING'),status:normalizedStatus(c.status,'DRAFT')},['prNo','sku']);if(entity==='purchaseOrders')return upsert(state.purchaseOrders,{id:uid(),poNo:c.poNo,prNo:c.prNo||'',supplierCode:c.supplierCode,sku:c.sku,qty:c.qty,unitPrice:c.unitPrice??0,dueDate:c.dueDate||'',grnNo:c.grnNo||'',invoiceNo:c.invoiceNo||'',status:normalizedStatus(c.status,'DRAFT')},['poNo','sku']);if(entity==='receipts'){const transaction=normalizedStatus(c.transaction,'GOODS_RECEIPT'),destination=c.warehouse;if(transaction==='GOODS_RECEIPT'){const receiptId=uid(),inspectionId=uid();queueReceiptForApproval(state,{id:receiptId,inspectionId,inspectionNo:id('IQC',state.qualityInspections),date:c.date||new Date().toISOString().slice(0,10),reference:c.reference,sku:c.sku,description:sku(c.sku)?.name||'',targetWarehouse:destination,qty:c.qty,supplier:c.supplier||'',notes:c.notes||'',transactionType:'GOODS_RECEIPT_QUARANTINE',postedAt:new Date().toISOString()})}else{state.stock[c.sku]??={};if(c.sourceWarehouse)state.stock[c.sku][c.sourceWarehouse]=(+state.stock[c.sku][c.sourceWarehouse]||0)-c.qty;state.stock[c.sku][destination]=(+state.stock[c.sku][destination]||0)+c.qty;state.receipts.unshift({id:uid(),date:c.date,reference:c.reference,sku:c.sku,warehouse:destination,sourceWarehouse:c.sourceWarehouse,qty:c.qty,supplier:c.supplier||'',notes:c.notes||'',batchNo:c.batch||'',status:'POSTED',transactionType:transaction,postedAt:new Date().toISOString()})}return'created'}if(entity==='quality')return upsert(state.qualityInspections,{id:uid(),inspectionNo:c.inspectionNo,type:normalizedStatus(c.type,'IQC'),reference:c.reference||'',date:c.date||new Date().toISOString().slice(0,10),sku:c.sku,qty:c.qty??0,result:normalizedStatus(c.result,'PENDING'),inspector:c.inspector||'',ncrNo:c.ncrNo||'',notes:c.notes||''},['inspectionNo']);if(entity==='invoices'){state.invoices??=[];return upsert(state.invoices,{id:uid(),...c,type:normalizedStatus(c.type,'SALES'),status:normalizedStatus(c.status,'OPEN')},['invoiceNo'])}if(entity==='shipments')return upsert(state.shipments,{id:uid(),shipmentNo:c.shipmentNo,orderNo:c.orderNo,pickQty:c.pickQty,packingList:c.packingList||'',invoiceNo:c.invoiceNo||'',oqcStatus:normalizedStatus(c.oqcStatus,'PENDING'),shippingRelease:'BLOCKED',podNo:c.podNo||'',status:normalizedStatus(c.status,'DRAFT')},['shipmentNo']);return'ignored'}

async function postUniversalImport(){
  if(!importSession||importSession.type!=='universal')return;
  const ready=importSession.results.filter(result=>result.status==='READY'),blocked=importSession.results.length-ready.length,stats={created:0,updated:0,ignored:0};
  for(const result of ready){const record=safeUniversalRecord(importSession.entity,result.clean),action=postUniversalRecord(importSession.entity,record);if(importSession.entity==='skus'&&record.barcode)sku(record.code).barcode=record.barcode;stats[action]=(stats[action]||0)+1}
  state.importHistory??=[];state.importHistory.unshift({id:crypto.randomUUID?.()||String(Date.now()),at:new Date().toISOString(),fileName:importSession.fileName,entity:importSession.entity,rows:importSession.results.length,ready:ready.length,blocked,unique:importSession.analysis?.unique||ready.length,duplicates:importSession.analysis?.duplicateRows||0,...stats,...operationMeta()});
  dirty('UNIVERSAL_IMPORT_POSTED','IMPORT',importSession.fileName,`${ready.length} rows · ${stats.created} created · ${stats.updated} updated`);await save();closeImportReview();renderAll();toast(`Import completed: ${stats.created} created, ${stats.updated} updated, ${blocked} blocked.`)
}

