function renderLiveScanResult(){const target=$('#liveScanResult');if(!target)return;const result=liveScanIdentification;if(!result){target.innerHTML='<p class="section-hint">Scan a code. Hamvara will show the matched record before changing the operator terminal.</p>';return}if(result.status==='NOT_FOUND'||result.status==='EMPTY'){const code=result.code||'';target.innerHTML=`<div class="smart-match not-found unknown-assign"><div><h3>Code not recognized</h3><p>${esc(code||'No code')} · Assign it now or create a new master record.</p><div class="unknown-assign-controls"><select id="unknownTargetKind"><option value="WORK_CENTER">Work station</option><option value="MACHINE">Machine</option><option value="OPERATION">Defined operation</option><option value="OPERATOR">Operator</option><option value="SKU">Item / SKU</option></select><select id="unknownTargetId"></select><button id="assignUnknownCode" class="gate-action">Assign this code</button><button id="createUnknownRecord">Create new record</button></div></div></div>`;const kind=$('#unknownTargetKind');kind.onchange=renderUnknownTargets;renderUnknownTargets();$('#assignUnknownCode').onclick=assignUnknownScannedCode;$('#createUnknownRecord').onclick=createUnknownScannedRecord;return}if(result.status==='AMBIGUOUS'){target.innerHTML=`<div class="smart-match ambiguous"><div><h3>More than one active record matched — select one</h3><p>${result.candidates.map((item,index)=>`<button data-scan-candidate="${index}">${esc(item.kind)}: ${esc(item.code)} — ${esc(item.label)}</button>`).join(' ')}</p></div></div>`;target.onclick=event=>{const button=event.target.closest('[data-scan-candidate]');if(!button)return;liveScanIdentification={...result,status:'MATCHED',match:result.candidates[Number(button.dataset.scanCandidate)]};renderLiveScanResult()};return}const item=shopFloorIdentificationSummary(state,result),extra=item.kind==='WORK_ORDER'?` · Qty ${n(item.quantity,2)} · Due ${esc(item.dueDate||'—')} · ${esc(item.deliveryRisk)}`:'';target.innerHTML=`<div class="smart-match"><div><h3>${esc(item.kind.replaceAll('_',' '))}: ${esc(item.code)} — ${esc(item.label)}</h3><p>${esc(item.details)}${extra}</p></div><button id="confirmLiveScan" class="gate-action">Confirm & Apply</button></div>`;target.onclick=null;$('#confirmLiveScan').onclick=confirmLiveScan}
function renderUnknownTargets(){const kind=$('#unknownTargetKind')?.value,target=$('#unknownTargetId');if(!target)return;target.innerHTML=barcodeTargets(state,kind).map(item=>`<option value="${esc(item.id)}">${esc(item.code)} — ${esc(item.label)}</option>`).join('')||'<option value="">No records — create one</option>'}
function assignUnknownScannedCode(){try{const kind=$('#unknownTargetKind').value,id=$('#unknownTargetId').value,code=liveScanIdentification?.code;const assigned=assignShopFloorBarcode(state,{kind,id,barcode:code});dirty('SHOP_FLOOR_BARCODE_ASSIGNED',assigned.kind,assigned.code,assigned.barcode);liveScanIdentification=identifyShopFloorCode(state,code);renderShopFloorLive();renderLiveScanResult();toast('Barcode assigned and ready to sync.')}catch(error){toast(error.message)}}
function createUnknownScannedRecord(){const kind=$('#unknownTargetKind').value,code=liveScanIdentification?.code,id=crypto.randomUUID?.()||String(Date.now()),label=`New ${kind.replaceAll('_',' ').toLowerCase()}`;if(kind==='OPERATOR')state.operators.unshift({id,code:`OP-${String(state.operators.length+1).padStart(3,'0')}`,barcode:'',name:label,shift:'A',hourlyRate:0,active:true});else if(['WORK_CENTER','MACHINE'].includes(kind))state.workCenters.unshift({id,code:`WC-${String(state.workCenters.length+1).padStart(3,'0')}`,barcode:'',machineBarcode:'',name:kind==='MACHINE'?'New machine station':label,machine:kind==='MACHINE'?'New machine':'',status:'AVAILABLE',hourlyRate:0,overheadRate:0,restartMinutes:0,reworkMinutesPerUnit:0,active:true});else if(kind==='OPERATION')state.shopFloorTasks.unshift({id,code:`OPERATION-${String(state.shopFloorTasks.length+1).padStart(3,'0')}`,name:label,barcode:'',description:'',active:true});else if(kind==='SKU'){state.skus.unshift({code:`SKU-${Date.now()}`,barcode:'',name:label,type:'COMPONENT',category:'',unit:'ADET',cost:0,warehouse:'WH-RM',supplier:'',leadTime:0,min:0,max:0,active:true});state.stock[state.skus[0].code]=Object.fromEntries([...state.warehouses.map(w=>[w.code,0]),['reserved',0]])}const created=barcodeTargets(state,kind)[0];try{const assigned=assignShopFloorBarcode(state,{kind,id:created.id,barcode:code});dirty('SHOP_FLOOR_MASTER_CREATED_FROM_SCAN',kind,assigned.code,assigned.barcode);liveScanIdentification=identifyShopFloorCode(state,code);renderShopFloorLive();renderLiveScanResult();toast('New record created and barcode assigned.')}catch(error){toast(error.message)}}

function selectedBarcodeTargets(){const kind=$('#barcodeTargetKind').value,all=barcodeTargets(state,kind),ids=new Set([...document.querySelectorAll('[data-barcode-select]:checked')].map(input=>input.value));return all.filter(item=>ids.has(String(item.id)))}
function qrDataUrl(value){const holder=document.createElement('div');new QRCode(holder,{text:value,width:180,height:180,colorDark:'#111820',colorLight:'#ffffff',correctLevel:QRCode.CorrectLevel.M});return holder.querySelector('canvas')?.toDataURL('image/png')||holder.querySelector('img')?.src||''}
function renderBarcodeGenerator(){const kind=$('#barcodeTargetKind').value,rows=barcodeTargets(state,kind);$('#barcodeTargetTable').innerHTML='<thead><tr><th></th><th>Code</th><th>Name</th><th>Assigned barcode</th><th></th></tr></thead><tbody>'+rows.map(item=>`<tr><td><input type="checkbox" data-barcode-select value="${esc(item.id)}"></td><td>${esc(item.code)}</td><td>${esc(item.label)}</td><td class="barcode-value">${esc(item.barcode||'Not generated')}</td><td><button data-preview-barcode="${esc(item.id)}">Preview</button></td></tr>`).join('')+'</tbody>';$('#barcodeTargetTable').onchange=renderBarcodePreview;$('#barcodeTargetTable').onclick=event=>{const button=event.target.closest('[data-preview-barcode]');if(!button)return;document.querySelectorAll('[data-barcode-select]').forEach(input=>input.checked=input.value===button.dataset.previewBarcode);renderBarcodePreview()};renderBarcodePreview()}
function renderBarcodePreview(){const item=selectedBarcodeTargets()[0],target=$('#barcodeLabelPreview');if(!item){target.innerHTML='<p class="section-hint">Select an asset to preview its printable label.</p>';return}if(!item.barcode){target.innerHTML=`<div class="empty-barcode"><b>${esc(item.label)}</b><p>No permanent code yet. Click Generate selected.</p></div>`;return}target.innerHTML=`<div class="preview-label"><header><b>HAMVARA MRP</b><span>${esc(item.kind.replaceAll('_',' '))}</span></header><h3>${esc(item.label)}</h3><p>${esc(item.code)}</p><div class="preview-codes"><img src="${qrDataUrl(item.barcode)}" alt="QR code">${code128Svg(item.barcode,{width:300,height:80})}</div><b>${esc(item.barcode)}</b></div>`}
