async function confirmLiveScan(){const match=liveScanIdentification?.match;if(!match)return;renderOperatorTerminal();if(match.kind==='OPERATOR')$('#liveOperator').value=match.id;else if(['WORK_CENTER','MACHINE'].includes(match.kind))$('#liveWorkCenter').value=match.id;else if(match.kind==='WORK_ORDER'){$('#liveWorkOrder').value=match.id;renderOperatorTerminal()}else if(match.kind==='OPERATION'){const stage=$('#liveStage');if([...stage.options].some(option=>option.value===match.code))stage.value=match.code;else return toast('This operation is not the next required stage for the selected work order.')}if(remoteScanEventId&&cloud?.enabled){await cloud.request(`/api/mrp/scan-events/${remoteScanEventId}/confirm`,{method:'POST',body:JSON.stringify({status:'CONFIRMED',result:shopFloorIdentificationSummary(state,liveScanIdentification)})}).catch(error=>toast(error.message));remoteScanEventId=''}appendAudit(state,{...operationMeta(),action:'SHOP_FLOOR_BARCODE_CONFIRMED',entity:'SHOP_FLOOR',reference:match.code,details:match.kind});dirty(null);$('#liveSmartScan').value='';liveScanIdentification=null;renderLiveScanResult();toast(`${match.kind.replaceAll('_',' ')} confirmed.`)}

async function startMobilePairing(){if(!cloud?.enabled)return toast('Mobile pairing requires a signed-in Hamvara cloud workspace.');try{await closeMobilePairing(false);const session=await cloud.request('/api/mrp/scan-sessions',{method:'POST',body:'{}'});mobilePairSession={...session,lastSequence:0};mobilePairLink=new URL('mobile-scan.html',location.href).toString().split('#')[0]+`#token=${encodeURIComponent(session.token)}`;const panel=$('#mobilePairPanel'),qr=$('#mobilePairQr');panel.hidden=false;qr.innerHTML='';new QRCode(qr,{text:mobilePairLink,width:180,height:180,colorDark:'#111820',colorLight:'#ffffff',correctLevel:QRCode.CorrectLevel.M});$('#mobilePairStatus').textContent='Scan this QR with the phone. Waiting for the secure device connection…';updateMobilePairCountdown();mobilePairTimer=setInterval(pollMobilePairing,1000);await pollMobilePairing()}catch(error){toast(`Could not create mobile connection: ${error.message}`)}}
async function pollMobilePairing(){if(!mobilePairSession||!cloud?.enabled)return;updateMobilePairCountdown();try{const payload=await cloud.request(`/api/mrp/scan-sessions/${mobilePairSession.id}/events?after=${mobilePairSession.lastSequence}`);if(payload.session.connected)$('#mobilePairStatus').textContent='Mobile device connected securely. Scan a barcode on the phone.';for(const event of payload.events){mobilePairSession.lastSequence=Math.max(mobilePairSession.lastSequence,event.sequence);remoteScanEventId=event.id;$('#liveSmartScan').value=event.code;analyzeLiveScan();const result=liveScanIdentification?.match?shopFloorIdentificationSummary(state,liveScanIdentification):{kind:'UNKNOWN',code:event.code,label:'Code not recognized'};await cloud.request(`/api/mrp/scan-events/${event.id}/confirm`,{method:'POST',body:JSON.stringify({status:'REVIEWED',result})});$('#mobilePairStatus').textContent=`Received ${event.code}. Review and confirm on this terminal.`;navigator.vibrate?.(80)}}catch(error){if(error.status===410){$('#mobilePairStatus').textContent='Connection expired. Create a new pairing session.';clearInterval(mobilePairTimer);mobilePairTimer=null}else toast(error.message)}}
function updateMobilePairCountdown(){if(!mobilePairSession)return;const seconds=Math.max(0,Math.ceil((Date.parse(mobilePairSession.expiresAt)-Date.now())/1000));$('#mobilePairCountdown').textContent=`${Math.floor(seconds/60)}:${String(seconds%60).padStart(2,'0')}`}
async function closeMobilePairing(notify=true){clearInterval(mobilePairTimer);mobilePairTimer=null;const session=mobilePairSession;mobilePairSession=null;mobilePairLink='';$('#mobilePairPanel').hidden=true;$('#mobilePairQr').innerHTML='';if(session&&cloud?.enabled)await cloud.request(`/api/mrp/scan-sessions/${session.id}/close`,{method:'POST',body:'{}'}).catch(()=>{});if(notify&&session)toast('Mobile camera disconnected.')}
async function startLiveCamera(){if(!navigator.mediaDevices?.getUserMedia){toast('Camera access requires HTTPS and browser permission.');return}if(!('BarcodeDetector'in window)){toast('This browser cannot decode barcodes from camera. Use a USB/Bluetooth scanner or enter the code.');$('#liveSmartScan').focus();return}try{stopLiveCamera();liveScannerStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}}});const video=$('#liveScannerVideo');video.srcObject=liveScannerStream;video.hidden=false;await video.play();const supported=await BarcodeDetector.getSupportedFormats?.()||[],formats=['code_128','qr_code','ean_13','ean_8','upc_a','data_matrix'].filter(format=>!supported.length||supported.includes(format)),detector=new BarcodeDetector({formats});const scan=async()=>{if(!liveScannerStream)return;const codes=await detector.detect(video).catch(()=>[]);if(codes[0]?.rawValue){$('#liveSmartScan').value=codes[0].rawValue;stopLiveCamera();analyzeLiveScan();navigator.vibrate?.(100);return}requestAnimationFrame(scan)};scan()}catch(error){stopLiveCamera();toast(`Camera unavailable: ${error.message}`)}}
function stopLiveCamera(){liveScannerStream?.getTracks().forEach(track=>track.stop());liveScannerStream=null;const video=$('#liveScannerVideo');if(video){video.srcObject=null;video.hidden=true}}
function renderOperatorTerminal(){const operator=$('#liveOperator'),jobSelect=$('#liveWorkOrder'),center=$('#liveWorkCenter'),oldOperator=operator.value,oldJob=jobSelect.value,oldCenter=center.value,operators=state.operators.filter(item=>item.active),jobs=state.productionJobs.filter(item=>item.status==='IN_PRODUCTION'),centers=state.workCenters.filter(item=>item.active&&item.status!=='MAINTENANCE'&&item.status!=='OFFLINE');operator.innerHTML=operators.map(item=>`<option value="${esc(item.id)}">${esc(item.code)} — ${esc(item.name)} · Shift ${esc(item.shift)}</option>`).join('')||'<option value="">No active operators</option>';jobSelect.innerHTML=jobs.map(item=>`<option value="${esc(item.id)}">${esc(item.workOrderNo)} — ${esc(item.productName)} · ${esc(item.batchNo)}</option>`).join('')||'<option value="">No issued work orders</option>';center.innerHTML=centers.map(item=>`<option value="${esc(item.id)}">${esc(item.code)} — ${esc(item.name)} ${item.machine?'· '+esc(item.machine):''}</option>`).join('')||'<option value="">No work centers</option>';if(operators.some(x=>x.id===oldOperator))operator.value=oldOperator;if(jobs.some(x=>x.id===oldJob))jobSelect.value=oldJob;if(centers.some(x=>x.id===oldCenter))center.value=oldCenter;const workOrder=state.productionJobs.find(item=>item.id===jobSelect.value),stage=workOrder?nextRequiredStage(state,workOrder.id):'';$('#liveStage').innerHTML=stage?`<option value="${esc(stage)}">${esc(stage.replaceAll('_',' '))}</option>`:'<option value="">No remaining stage</option>';if(workOrder&&($('#liveInputQty').dataset.jobId!==workOrder.id||!$('#liveInputQty').value)){$('#liveInputQty').value=expectedStageInput(state,workOrder.id);$('#liveInputQty').dataset.jobId=workOrder.id}$('#startLiveOperation').disabled=!operators.length||!jobs.length||!centers.length||!stage;$('#raiseAndon').disabled=!jobs.length}
function startLiveOperation(){try{const session=startOperation(state,{operatorId:$('#liveOperator').value,jobId:$('#liveWorkOrder').value,stage:$('#liveStage').value,workCenterId:$('#liveWorkCenter').value,inputQty:parseLocalizedNumber($('#liveInputQty').value)},operationMeta());dirty(null);renderAll();toast(`${session.operatorName} started ${session.stage.replaceAll('_',' ')}.`)}catch(error){toast(error.message)}}
function raiseLiveAndon(){const jobId=$('#liveWorkOrder').value;if(!jobId)return toast('Select a work order first.');const category=(prompt('Andon category: QUALITY, MACHINE, MATERIAL, SAFETY or OTHER','MACHINE')||'OTHER').trim().toUpperCase(),message=(prompt('Describe the problem','Assistance required')||'Assistance required').trim();try{const alert=raiseAndon(state,{jobId,operatorId:$('#liveOperator').value,category,severity:category==='SAFETY'?'CRITICAL':'HIGH',message},operationMeta());if(category==='QUALITY'){state.qualityInspections.unshift({id:crypto.randomUUID?.()||String(Date.now()),inspectionNo:id('IPQC',state.qualityInspections),type:'IPQC',reference:alert.workOrderNo,sku:state.productionJobs.find(item=>item.id===jobId)?.outputSku||'',qty:0,result:'PENDING',date:new Date().toISOString().slice(0,10),ncrNo:'',disposition:'HOLD',released:false,notes:`Andon ${alert.id}: ${message}`,andonId:alert.id})}dirty(null);renderAll();toast('Andon raised and improvement action created.')}catch(error){toast(error.message)}}
function handleLiveOperationAction(sessionId,action,card){try{if(action==='pause')pauseOperation(state,sessionId,{reason:card.querySelector('[data-live-reason]').value||'UNSPECIFIED',meta:operationMeta()});else if(action==='resume')resumeOperation(state,sessionId,{meta:operationMeta()});else if(action==='complete')completeOperation(state,sessionId,{goodQty:parseLocalizedNumber(card.querySelector('[data-live-good]').value),scrapQty:parseLocalizedNumber(card.querySelector('[data-live-scrap]').value),reworkQty:parseLocalizedNumber(card.querySelector('[data-live-rework]').value),notes:card.querySelector('[data-live-notes]').value},operationMeta());dirty(null);renderAll();toast(action==='complete'?'Operation completed; next stage is available.':`Operation ${action}d.`)}catch(error){toast(error.message)}}
function linkImprovementProject(item,projectId){item.projectId=projectId;if(!projectId)return;let task=state.projectTasks.find(task=>task.id===item.projectTaskId);if(!task){task={id:crypto.randomUUID?.()||String(Date.now()),projectId,title:item.description||'Continuous improvement action',phase:'Improve',status:'BACKLOG',owner:item.actionOwner||'',dueDate:'',priority:item.severity==='CRITICAL'?'CRITICAL':'HIGH',progress:0,linkedEntityType:'PRODUCTION_ORDER',linkedEntityId:item.workOrderNo};state.projectTasks.push(task);item.projectTaskId=task.id}}
