  const sources=[['MANUAL','Manual entry'],['PROJECT_PROGRESS','Project progress'],['TASKS_ON_TIME','Tasks on time'],['BLOCKED_TASKS','Blocked tasks'],['PRODUCTION_YIELD','Production yield'],['OVERDUE_WORK_ORDERS','Overdue work orders'],['QUALITY_REJECT_RATE','Quality reject rate'],['CRITICAL_STOCK','Critical stock items']];$('#projectKpiTable').innerHTML='<thead><tr><th>KPI</th><th>Data source</th><th>Target</th><th>Direction</th><th>Manual actual</th><th>Live actual</th><th>Status</th><th></th></tr></thead><tbody>'+health.map(kpi=>`<tr data-kpi-id="${esc(kpi.id)}"><td><input data-kpi-field="name" value="${esc(kpi.name)}"></td><td><select data-kpi-field="source">${sources.map(([value,label])=>`<option value="${value}" ${kpi.source===value?'selected':''}>${label}</option>`).join('')}</select></td><td><input data-kpi-field="target" data-number="true" value="${esc(kpi.target)}"></td><td><select data-kpi-field="direction"><option value="ABOVE" ${kpi.direction==='ABOVE'?'selected':''}>At least</option><option value="BELOW" ${kpi.direction==='BELOW'?'selected':''}>At most</option></select></td><td><input data-kpi-field="manualActual" data-number="true" value="${esc(kpi.manualActual)}" ${kpi.source!=='MANUAL'?'disabled':''}></td><td>${n(kpi.actual,2)} ${esc(kpi.unit)}</td><td>${chip(kpi.status)}</td><td><button data-delete-kpi class="delete">Delete</button></td></tr>`).join('')+'</tbody>';
