function renderProjectTaskPlanning(project){const tasks=state.projectTasks.filter(item=>item.projectId===project.id),milestones=state.projectMilestones.filter(item=>item.projectId===project.id),sprints=state.projectSprints.filter(item=>item.projectId===project.id);$('#projectTaskPlanningTable').innerHTML='<thead><tr><th>Task</th><th>Phase</th><th>Start</th><th>Due</th><th>Milestone</th><th>Sprint</th><th>Progress</th></tr></thead><tbody>'+tasks.map(task=>`<tr data-plan-task-id="${esc(task.id)}"><td>${esc(task.title)}</td><td><input data-plan-task-field="phase" value="${esc(task.phase)}"></td><td><input data-plan-task-field="startDate" type="date" value="${esc(task.startDate)}"></td><td><input data-plan-task-field="dueDate" type="date" value="${esc(task.dueDate)}"></td><td><select data-plan-task-field="milestoneId"><option value="">Unassigned</option>${milestones.map(item=>`<option value="${esc(item.id)}" ${task.milestoneId===item.id?'selected':''}>${esc(item.name)}</option>`).join('')}</select></td><td><select data-plan-task-field="sprintId"><option value="">Backlog</option>${sprints.map(item=>`<option value="${esc(item.id)}" ${task.sprintId===item.id?'selected':''}>${esc(item.name)}</option>`).join('')}</select></td><td>${n(task.progress,0)}%</td></tr>`).join('')+'</tbody>';editCollectionTable($('#projectTaskPlanningTable'),state.projectTasks,'data-plan-task-id','data-plan-task-field',renderProjects)}
function addProjectFinance(){const project=activeProject();if(!project)return toast('Create a project first.');state.projectFinance.push({id:crypto.randomUUID?.()||String(Date.now()),projectId:project.id,date:new Date().toISOString().slice(0,10),type:'PLANNED',description:'New project cost',reference:'',amount:0,status:'DRAFT'});dirty('PROJECT_FINANCE_CREATED','PROJECT',project.code);renderProjects()}
function addProjectLink(){const project=activeProject();if(!project)return toast('Create a project first.');state.projectErpLinks??=[];state.projectErpLinks.push({id:crypto.randomUUID?.()||String(Date.now()),projectId:project.id,taskId:'',type:'PRODUCTION_ORDER',reference:'',status:'PENDING'});dirty('PROJECT_LINK_CREATED','PROJECT',project.code);renderProjects()}
function clearErpLink(link){const config=ERP_LINKS[link?.type];if(!config)return;for(const record of state[config.collection]||[]){const sameReference=config.keys.some(key=>String(record[key]||'')===String(link.reference||''));if(record.projectId===link.projectId&&sameReference){record.projectId='';record.projectTaskId=''}}const task=state.projectTasks.find(item=>item.id===link?.taskId);if(task&&task.linkedEntityType===link.type&&task.linkedEntityId===link.reference){task.linkedEntityType='';task.linkedEntityId='';task.linkStatus=''}}
function editCollectionTable(container,collection,idField,dataField,rerender){container.onchange=e=>{const el=e.target.closest(`[${dataField}]`);if(!el)return;const row=collection.find(item=>item.id===el.closest(`[${idField}]`).getAttribute(idField));if(!row)return;if(dataField==='data-link-field')clearErpLink(row);const field=el.getAttribute(dataField);row[field]=el.dataset.number?parseLocalizedNumber(el.value)||0:el.value;dirty('PROJECT_METHOD_UPDATED','PROJECT',activeProject()?.code||'',field);rerender()};container.onclick=e=>{const button=e.target.closest('[data-row-delete]');if(!button)return;const id=button.closest(`[${idField}]`).getAttribute(idField),index=collection.findIndex(item=>item.id===id);if(index>=0){if(dataField==='data-link-field')clearErpLink(collection[index]);collection.splice(index,1)}dirty('PROJECT_METHOD_ROW_DELETED','PROJECT',activeProject()?.code||'',id);rerender()}}
