  $('#shiftCalendarTable').onchange=event=>{const field=event.target.dataset.shiftField;if(!field)return;const item=shifts.find(value=>value.id===event.target.closest('tr').dataset.shiftId),before=item.code;item[field]=field==='active'?event.target.checked:['dailyHours','workDays','efficiencyPercent'].includes(field)?parseLocalizedNumber(event.target.value):event.target.value.trim();if(field==='code'){state.workCenters.filter(value=>value.shiftCode===before).forEach(value=>value.shiftCode=item.code);state.operators.filter(value=>value.shift===before).forEach(value=>value.shift=item.code);state.productRoutings.filter(value=>value.shiftCode===before).forEach(value=>value.shiftCode=item.code)}dirty('SHIFT_CALENDAR_UPDATED','PRODUCTION',item.code,field);renderAdvancedPlanning()};
  $('#shiftCalendarTable').onclick=event=>{const button=event.target.closest('[data-delete-shift]');if(!button)return;if(shifts.length===1){toast('At least one shift is required.');return}const id=button.closest('tr').dataset.shiftId;state.shiftCalendars=shifts.filter(item=>item.id!==id);dirty('SHIFT_CALENDAR_DELETED','PRODUCTION',id);renderAdvancedPlanning()};
