function renderEngineeringChanges(){normalizeEngineeringChanges(state);const prior=$('#ecoProduct').value;$('#ecoProduct').innerHTML=state.products.map(item=>`<option value="${esc(item.code)}">${esc(item.code)} — ${esc(item.name)}</option>`).join('');if(state.products.some(item=>item.code===prior))$('#ecoProduct').value=prior;$('#ecoTable').innerHTML='<thead><tr><th>ECO</th><th>Product</th><th>Type</th><th>Title</th><th>Effective</th><th>BOM</th><th>Routing</th><th>Requester</th><th>Reviewer</th><th>Approver</th><th>Status</th><th>Gate</th></tr></thead><tbody>'+state.engineeringChanges.map(item=>{const label=({DRAFT:'Submit',SUBMITTED:'Technical review',TECHNICAL_REVIEW:'Approve',APPROVED:'Release'})[item.status]||item.status;return`<tr data-eco-id="${esc(item.id)}"><td>${esc(item.ecoNo)}</td><td>${esc(item.productCode)}</td><td>${esc(item.type)}</td><td>${esc(item.title)}</td><td>${esc(item.effectiveDate)}</td><td>${esc(item.targetBomVersion||'—')}</td><td>${esc(item.routingRevision||'—')}</td><td>${esc(item.requestedBy)}</td><td>${esc(item.reviewedBy||'—')}</td><td>${esc(item.approvedBy||'—')}</td><td>${chip(item.status)}</td><td><button data-eco-action class="gate-action" ${['RELEASED','REJECTED','CANCELLED'].includes(item.status)?'disabled':''}>${esc(label)}</button></td></tr>`}).join('')+'</tbody>';$('#ecoTable').onclick=event=>{const button=event.target.closest('[data-eco-action]');if(!button)return;const item=state.engineeringChanges.find(value=>value.id===button.closest('tr').dataset.ecoId);try{if(item.status==='DRAFT')submitEngineeringChange(state,item.id,{user:item.requestedBy});else if(item.status==='SUBMITTED')reviewEngineeringChange(state,item.id,{user:$('#ecoReviewer').value.trim()});else if(item.status==='TECHNICAL_REVIEW')approveEngineeringChange(state,item.id,{user:$('#ecoApprover').value.trim()});else if(item.status==='APPROVED')releaseEngineeringChange(state,item.id,{user:$('#ecoApprover').value.trim()});dirty(`ECO_${item.status}`,'ENGINEERING_CHANGE',item.ecoNo,item.productCode);renderAdvancedPlanning()}catch(error){toast(error.message)}}}
function addEngineeringChange(){try{const item=createEngineeringChange(state,{productCode:$('#ecoProduct').value,type:$('#ecoType').value,title:$('#ecoTitle').value,reason:$('#ecoReason').value,impact:$('#ecoImpact').value,risk:$('#ecoRisk').value,targetBomVersion:$('#ecoBomVersion').value,routingRevision:$('#ecoRoutingRevision').value,effectiveDate:$('#ecoEffectiveDate').value,requestedBy:$('#ecoRequester').value.trim()},operationMeta());dirty('ECO_CREATED','ENGINEERING_CHANGE',item.ecoNo,item.productCode);renderAdvancedPlanning();toast(`${item.ecoNo} created as draft.`)}catch(error){toast(error.message)}}
function renderCycleCounting(){normalizeCycleCounting(state);const prior=$('#cycleCountWarehouse').value;$('#cycleCountWarehouse').innerHTML=state.warehouses.map(item=>`<option value="${esc(item.code)}">${esc(item.code)} — ${esc(warehouseName(item))}</option>`).join('');if(state.warehouses.some(item=>item.code===prior))$('#cycleCountWarehouse').value=prior;state.cycleCountSettings.valueApprovalThreshold=Math.max(0,parseLocalizedNumber($('#cycleCountThreshold').value)||state.cycleCountSettings.valueApprovalThreshold);const warehouse=$('#cycleCountWarehouse').value,accuracy=cycleCountAccuracy(state,{warehouse}),due=warehouse?dueCycleCountItems(state,{warehouse}).length:0,open=state.cycleCounts.filter(item=>item.warehouse===warehouse&&['OPEN','SUBMITTED','REVIEW_REQUIRED'].includes(item.status));$('#cycleCountKpis').innerHTML=[['Due SKU',due],['Open counts',open.length],['Line accuracy',`${n(accuracy.lineAccuracy,2)}%`],['Quantity accuracy',`${n(accuracy.quantityAccuracy,2)}%`]].map(([label,value])=>`<div class="kpi">${label}<b>${value}</b></div>`).join('');$('#inventoryAccuracyStatus').textContent=accuracy.lines?`${n(accuracy.lineAccuracy,1)}% LINE ACCURACY`:'NO APPROVED COUNTS';$('#inventoryAccuracyStatus').className=`status-chip ${accuracy.lines&&accuracy.lineAccuracy>=98?'ok':accuracy.lines?'warn':'neutral'}`;const rows=state.cycleCounts.filter(item=>!warehouse||item.warehouse===warehouse);$('#cycleCountRegister').innerHTML='<thead><tr><th>Count</th><th>Warehouse</th><th>Scope</th><th>Lines</th><th>Requester</th><th>Counter</th><th>Approver</th><th>Status</th><th>Action</th></tr></thead><tbody>'+rows.map(item=>`<tr data-count-id="${esc(item.id)}"><td>${esc(item.countNo)}</td><td>${esc(item.warehouse)}</td><td>${esc(item.scope)}</td><td>${item.lines.length}</td><td>${esc(item.requestedBy)}</td><td>${esc(item.counter||'—')}</td><td>${esc(item.approver||'—')}</td><td>${chip(item.status)}</td><td><button data-count-action class="gate-action" ${item.status==='APPROVED'?'disabled':''}>${item.status==='OPEN'?'Submit count':['SUBMITTED','REVIEW_REQUIRED'].includes(item.status)?'Approve & post':'Completed'}</button></td></tr>`).join('')+'</tbody>';$('#cycleCountRegister').onclick=event=>{const row=event.target.closest('tr[data-count-id]');if(!row)return;const count=state.cycleCounts.find(item=>item.id===row.dataset.countId);renderCycleCountSheet(count);if(event.target.closest('[data-count-action]'))processCycleCount(count)};renderCycleCountSheet(open[0]||rows[0])}
function renderCycleCountSheet(count){const target=$('#cycleCountSheet');if(!count){target.innerHTML='';return}const blind=count.status==='OPEN';target.innerHTML=`<div class="cycle-count-sheet"><h3>${esc(count.countNo)} Count Sheet</h3>${blind?'<div class="blind-count-note">Blind count: expected system quantities remain hidden until submission.</div>':''}<div class="table-wrap process-table"><table><thead><tr><th>SKU</th><th>Description</th><th>Bin</th><th>ABC</th><th>Expected</th><th>Counted</th><th>Variance</th><th>Variance value</th></tr></thead><tbody>${count.lines.map(line=>`<tr data-count-line="${esc(line.id)}"><td>${esc(line.sku)}</td><td>${esc(line.name)}</td><td>${esc(line.binLocation||'—')}</td><td>${esc(line.abcClass)}</td><td>${blind?'HIDDEN':n(line.expectedQty,4)}</td><td>${blind?`<input data-counted-qty data-number="true" inputmode="decimal" value="${line.countedQty??''}">`:n(line.countedQty,4)}</td><td>${blind?'—':n(line.varianceQty,4)}</td><td>${blind?'—':n(line.varianceValue,2)}</td></tr>`).join('')}</tbody></table></div></div>`}
function processCycleCount(count){try{if(count.status==='OPEN'){const values=Object.fromEntries([...document.querySelectorAll('#cycleCountSheet tr[data-count-line]')].map(row=>[row.dataset.countLine,row.querySelector('[data-counted-qty]')?.value]));submitCycleCount(state,count.id,{counter:$('#cycleCountCounter').value.trim(),counts:values})}else if(['SUBMITTED','REVIEW_REQUIRED'].includes(count.status))approveCycleCount(state,count.id,{approver:$('#cycleCountApprover').value.trim()});dirty(`CYCLE_COUNT_${count.status}`,'INVENTORY',count.countNo,count.warehouse);renderAdvancedPlanning()}catch(error){toast(error.message)}}
function addCycleCount(){try{state.cycleCountSettings.valueApprovalThreshold=Math.max(0,parseLocalizedNumber($('#cycleCountThreshold').value)||0);const count=createCycleCount(state,{warehouse:$('#cycleCountWarehouse').value,scope:$('#cycleCountScope').value,requestedBy:$('#cycleCountRequester').value.trim()});dirty('CYCLE_COUNT_CREATED','INVENTORY',count.countNo,count.warehouse);renderAdvancedPlanning();toast(`${count.countNo} blind count created.`)}catch(error){toast(error.message)}}

